    use super::*;

    #[test]
    #[ignore]
    fn empty_list() {
        let list = vec![0.0f64; 0].into_iter();
        let initial = 2.0;
        let output = foldr(list, initial, |acc, el| el * acc);

        let expected = 2.0;

        assert_eq!(output, expected);
    }

    #[test]
    #[ignore]
    fn direction_independent_function_applied_to_non_empty_list() {
        let list = vec![1.0, 2.0, 3.0, 4.0].into_iter();
        let initial = 5.0;
        let output = foldr(list, initial, |acc, el| el + acc);

        let expected = 15.0;

        assert_eq!(output, expected);
    }

    #[test]
    #[ignore]
